"""Permissions: allow / ask / deny rules, and a y/n prompt in the terminal.

Rules look like Claude Code's: "read_file", "bash(pytest*)", "edit_file(src/*)", "*".
The part in parentheses is a glob matched against the call's subject (the command or path).
Order of precedence: deny, then ask, then allow, then the default for the tool.
"""
from __future__ import annotations

import fnmatch
import glob
import re
from dataclasses import dataclass
from typing import Callable

READ_ONLY = {"read_file", "list_dir", "grep", "task"}  # safe by default: they change nothing
DEFAULT_DENY = ["bash(rm -rf /*)", "bash(rm -rf ~*)", "bash(sudo *)", "bash(*mkfs*)", "bash(*:(){*)",
                "bash(git push*)"]


@dataclass
class Rule:
    tool: str            # tool-name glob
    pattern: str | None  # subject glob, or None for "any call to this tool"

    def matches(self, tool: str, subject: str) -> bool:
        """Part 3: True if the tool name matches self.tool (a glob) and, when self.pattern is
        set, the subject matches self.pattern (a glob). Use fnmatch.fnmatchcase."""
        raise NotImplementedError("Part 3: implement Rule.matches (see the docstring)")

    def __str__(self) -> str:
        return self.tool if self.pattern is None else f"{self.tool}({self.pattern})"


def parse_rule(text: str) -> Rule:
    """Part 3: Parse "bash(git *)" into Rule("bash", "git *") and "read_file" into
    Rule("read_file", None). Raise ValueError on anything else."""
    raise NotImplementedError("Part 3: implement parse_rule (see the docstring)")


def subject_of(tool: str, args: dict) -> str:
    """What a rule pattern is matched against: the command for bash, else the path."""
    if tool == "bash":
        return str(args.get("command", ""))
    if tool == "task":
        return str(args.get("description", ""))
    return str(args.get("path", ".")).removeprefix("./")


def _ask_terminal(question: str) -> str:
    try:
        return input(question)
    except EOFError:  # no terminal (piped, CI): treat as "no"
        return ""


class Permissions:
    def __init__(self, allow: list[str] = (), ask: list[str] = (), deny: list[str] = DEFAULT_DENY,
                 yes: bool = False, prompt: Callable[[str], str] = _ask_terminal):
        self.allow = [parse_rule(r) for r in allow]
        self.ask = [parse_rule(r) for r in ask]
        self.deny = [parse_rule(r) for r in deny]
        self.yes = yes          # --yes: approve calls that would otherwise be asked by default
        self.prompt = prompt    # injectable for tests
        self.log: list[tuple[str, str, str]] = []  # (tool, subject, outcome)

    @classmethod
    def from_config(cls, cfg: dict, **kw) -> "Permissions":
        p = cfg.get("permissions", {})
        return cls(p.get("allow", []), p.get("ask", []), list(DEFAULT_DENY) + p.get("deny", []), **kw)

